Rules.InvariantScript:
If(!varCargado,
    Concurrent(
        ClearCollect(colPersonal, tblPersonal),
        If(IsError(ClearCollect(colIngresos, tblIngresos)), false),
        ClearCollect(colHistorial, tblHistorial),
        ClearCollect(colDonantes, tblDonantes)
    );
    Set(varYo, LookUp(colPersonal, Lower(Trim(Correo)) = Lower(User().Email) && Activo = "Sí"));
    Set(varArea, If(IsBlank(varYo), "Sin acceso", varYo.Area));
    Set(varCargado, true)
);
If(IsBlank(varTema), Set(varTema, "claro"));
IfError(ClearCollect(colGestiones, Filter(tblGestiones, Id <> "0")); true, Notify("No se pudo leer tblGestiones (App_Biblioteca_Datos.xlsx). En Power Apps: Datos → tblGestiones → ⋯ → Actualizar.", NotificationType.Error); false);
If(IsBlank(varVistaMo), Set(varVistaMo, "Por usuario")); Set(varOpcCorreoMo, false);
If(IsBlank(varNivelMo), Set(varNivelMo, "Todos los niveles")); Reset(drpTramoMo);
If(IsBlank(varMorCargando), Set(varMorCargando, false); Set(varQMor, ""); ClearCollect(colMorDet, FirstN(Table({rut: "", nombre: "", tipo: "", biblioteca: "", titulo: "", codigo: "", vence: "", dias: 0, correo: ""}), 0)))

If(IsEmpty(colMorDet) && !varMorCargando,
    Set(varMorCargando, true);
    Set(varMorRes, IfError('FolioMorosos'.Run(""), Notify("No se pudo consultar FOLIO (flujo FolioMorosos): " & FirstError.Message, NotificationType.Error); Blank()));
    Set(varMorTxt, IfError(Text(varMorRes.datos), ""));
    ClearCollect(colMorAct, ForAll(Table(IfError(ParseJSON(Coalesce(IfError(Text(varMorRes.activos), ""), "[]")), ParseJSON("[]"))), {biblioteca: Text(ThisRecord.Value.biblioteca), activos: Value(ThisRecord.Value.activos), prestamos: Value(ThisRecord.Value.prestamos)}));
    ClearCollect(colMorDet, ForAll(Table(ParseJSON(If(IsBlank(varMorTxt), "[]", varMorTxt))), {rut: Text(ThisRecord.Value.rut), nombre: Text(ThisRecord.Value.nombre), tipo: Text(ThisRecord.Value.tipo), biblioteca: Text(ThisRecord.Value.biblioteca), titulo: Text(ThisRecord.Value.titulo), codigo: Text(ThisRecord.Value.codigo), vence: Text(ThisRecord.Value.vence), dias: Value(ThisRecord.Value.dias), correo: Text(ThisRecord.Value.correo)}));
    Set(varMorCargando, false)
)
